<?php declare(strict_types=1);return static function(PDO $db):void{$db->exec("CREATE TABLE IF NOT EXISTS treasury_ledger(id INT AUTO_INCREMENT PRIMARY KEY,movement_type VARCHAR(40) NOT NULL,direction VARCHAR(10) NOT NULL,amount DECIMAL(15,2) NOT NULL,movement_date DATE NOT NULL,reference VARCHAR(150) NULL,note TEXT NULL,created_by INT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_treasury_ledger_date(movement_date,movement_type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$db->exec("ALTER TABLE factures_clients ADD COLUMN IF NOT EXISTS expected_collection_date DATE NULL AFTER date_echeance");$db->exec("ALTER TABLE factures_clients ADD COLUMN IF NOT EXISTS collection_tracking_status VARCHAR(30) NOT NULL DEFAULT 'pending' AFTER expected_collection_date");$db->exec("ALTER TABLE factures_clients ADD COLUMN IF NOT EXISTS collection_tracking_note TEXT NULL AFTER collection_tracking_status");};
